import numpy as np
def classification(y,p):
 y=np.asarray(y,dtype=int);p=np.asarray(p,dtype=float);n=len(y);positive=int(y.sum());negative=n-positive;pred=p>=.5;tp=int((pred&(y==1)).sum());fp=int((pred&(y==0)).sum());fn=positive-tp;tn=negative-fp;order=np.argsort(-p,kind='mergesort');sy=y[order];sp=p[order];ends=np.r_[np.where(sp[1:]!=sp[:-1])[0],n-1];TP=np.cumsum(sy)[ends];FP=ends+1-TP;recall=TP/positive if positive else np.zeros_like(TP,float);precision=TP/(ends+1);AP=float(np.sum(np.diff(np.r_[0.,recall])*precision))if positive else None;auc=float(np.trapz(np.r_[0.,recall],np.r_[0.,FP/negative]))if positive and negative else None;pc=np.clip(p,1e-7,1-1e-7);bce=float(np.mean(-y*np.log(pc)-(1-y)*np.log(1-pc)))
 return dict(n=n,positive=positive,negative=negative,prevalence=positive/n,BCE=bce,AUROC=auc,AUPRC=AP,TP=tp,FP=fp,FN=fn,TN=tn,precision=tp/(tp+fp)if tp+fp else 0.,recall=tp/positive if positive else None,FPR=fp/negative if negative else None,FNR=fn/positive if positive else None,accuracy=(tp+tn)/n,threshold=.5)
